/* FizLab thinking tasks, set 2: contentions, troubleshooting, what-if, bar-chart, jeopardy and comparison questions,
   ranking tasks and estimates / Misaoni zadaci, drugi skup */
(function () {
  'use strict';
  window.Content.registerConcepts([

    /* ---------- MATTER / TVAR ---------- */
    { id: 't2-sugar-dissolves-mass', topic: 'matter', type: 'mc', format: 'contentions', level: 1,
      q: { en: 'The water in a glass has a mass of 200 g. Iva stirs in 10 g of sugar until it can no longer be seen. Ana says: "The mass is still 200 g, the sugar has disappeared." Marko says: "The mass is 210 g, all the sugar is still in the glass." Petra says: "A little less than 210 g, because dissolved sugar is lighter." Who is right?',
           hr: 'Voda u čaši ima masu 200 g. Iva u nju umiješa 10 g šećera, sve dok se šećer više ne vidi. Ana kaže: "Masa je i dalje 200 g, šećer je nestao." Marko kaže: "Masa je 210 g, sav je šećer još u čaši." Petra kaže: "Malo manje od 210 g, jer je otopljeni šećer lakši." Tko ima pravo?' },
      options: [ { en: 'Ana', hr: 'Ana' }, { en: 'Marko', hr: 'Marko' }, { en: 'Petra', hr: 'Petra' }, { en: 'none of them', hr: 'nitko od njih' } ],
      answer: 1,
      explain: { en: 'Dissolving does not destroy matter. The sugar breaks up into molecules too small to see, which spread among the water molecules, but every one of them is still in the glass, so the masses add up to 210 g. You can taste the sugar, and you get it back if you let the water evaporate.',
                 hr: 'Otapanjem tvar ne nestaje. Šećer se razdvoji na molekule premalene da bismo ih vidjeli i one se rasporede među molekulama vode, ali sve su i dalje u čaši, pa se mase zbrajaju: 210 g. Šećer možeš okusiti, a dobiješ ga natrag ako pustiš da voda ishlapi.' },
      misconception: { en: 'Many pupils believe that what can no longer be seen is no longer there, or that it has lost its weight. Mass is conserved in dissolving, melting and evaporating.',
                       hr: 'Mnogi učenici vjeruju da onoga što se više ne vidi više nema ili da je izgubilo težinu. Masa je očuvana pri otapanju, taljenju i isparavanju.' } },

    { id: 't2-rank-volumes-units', topic: 'matter', type: 'rank', level: 2,
      q: { en: 'Rank these amounts from the largest volume to the smallest.', hr: 'Poredaj ove količine od najvećeg obujma do najmanjeg.' },
      items: [ { en: '0.5 m³ of sand', hr: '0,5 m³ pijeska' }, { en: '200 L of rainwater in a barrel', hr: '200 L kišnice u bačvi' }, { en: '5000 cm³ of soil in a flowerpot', hr: '5000 cm³ zemlje u tegli za cvijeće' }, { en: '3 dm³ of milk', hr: '3 dm³ mlijeka' }, { en: '250 mL of juice', hr: '250 mL soka' } ],
      explain: { en: 'Convert everything to the same unit, for example litres: 1 m³ = 1000 L, 1 dm³ = 1 L, 1000 cm³ = 1 L and 1000 mL = 1 L. That gives 500 L, 200 L, 5 L, 3 L and 0.25 L. The number alone says nothing: 5000 looks huge, but 5000 cm³ is only 5 litres.',
                 hr: 'Sve pretvori u istu jedinicu, primjerice litre: 1 m³ = 1000 L, 1 dm³ = 1 L, 1000 cm³ = 1 L i 1000 mL = 1 L. Tako dobiješ 500 L, 200 L, 5 L, 3 L i 0,25 L. Sam broj ne govori ništa: 5000 izgleda golemo, ali 5000 cm³ je samo 5 litara.' } },

    /* ---------- DENSITY / GUSTOĆA ---------- */
    { id: 't2-steel-ferry-floats', topic: 'density', type: 'mc', format: 'contentions', level: 2,
      q: { en: 'A steel ferry sails from Split to Brač, although a steel nail sinks at once. Ana says: "The engines hold the ferry up." Luka says: "The ferry is a hollow shell full of air, so its average density is smaller than the density of water." Petra says: "The ferry floats because the sea is deep and there is a lot of water under it." Who is right?',
           hr: 'Čelični trajekt plovi od Splita do Brača, iako čelični čavao odmah potone. Ana kaže: "Trajekt na površini drže motori." Luka kaže: "Trajekt je šuplja ljuska puna zraka, pa mu je prosječna gustoća manja od gustoće vode." Petra kaže: "Trajekt pluta jer je more duboko i pod njim je mnogo vode." Tko ima pravo?' },
      options: [ { en: 'Ana', hr: 'Ana' }, { en: 'Luka', hr: 'Luka' }, { en: 'Petra', hr: 'Petra' }, { en: 'none of them', hr: 'nitko od njih' } ],
      answer: 1,
      explain: { en: 'What counts is the average density of the whole ship: the mass of the steel, the cargo and the air inside, divided by the whole volume of the hull. Most of that volume is air, so the average is less than the density of water and the ship floats, with the engines on or off. If the hull fills with water, the average density becomes greater than that of water and the ship sinks.',
                 hr: 'Važna je prosječna gustoća cijelog broda: masa čelika, tereta i zraka u njemu podijeljena s cijelim obujmom trupa. Najveći dio tog obujma je zrak, pa je prosjek manji od gustoće vode i brod pluta, radili motori ili ne. Ako se trup napuni vodom, prosječna gustoća postane veća od gustoće vode i brod potone.' },
      misconception: { en: 'Pupils look only at the material ("steel is heavy, so it must sink") or think that deep water carries a ship better. A ship floats just the same in a shallow harbour as on the open sea.',
                       hr: 'Učenici gledaju samo materijal ("čelik je težak, pa mora potonuti") ili misle da duboka voda bolje nosi brod. Brod jednako pluta u plitkoj luci i na otvorenom moru.' } },

    { id: 't2-rank-floating-depth', topic: 'density', type: 'rank', level: 3,
      q: { en: 'Four solid bodies float on a lake. Rank them from the one with the largest part of its volume under water to the one with the smallest part under water.',
           hr: 'Četiri puna tijela plutaju na jezeru. Poredaj ih od onoga kojemu je najveći dio obujma pod vodom do onoga kojemu je pod vodom najmanji dio.' },
      items: [ { en: 'a 50 kg block of ice (density 0.92 g/cm³)', hr: 'blok leda mase 50 kg (gustoća 0,92 g/cm³)' }, { en: 'a 500 kg oak log (density 0.70 g/cm³)', hr: 'hrastov trupac mase 500 kg (gustoća 0,70 g/cm³)' }, { en: 'a 20 g pine cube (density 0.50 g/cm³)', hr: 'kockica od borovine mase 20 g (gustoća 0,50 g/cm³)' }, { en: 'a 2 kg sheet of cork (density 0.24 g/cm³)', hr: 'ploča od pluta mase 2 kg (gustoća 0,24 g/cm³)' } ],
      explain: { en: 'The part of a floating body that is under water equals its density divided by the density of water (1 g/cm³): ice 92 %, oak 70 %, pine 50 %, cork 24 %. Mass and size play no role: the 500 kg log floats higher than the 50 kg block of ice, and a larger part of the 20 g cube is under water than of the 2 kg sheet of cork.',
                 hr: 'Dio plutajućeg tijela koji je pod vodom jednak je omjeru njegove gustoće i gustoće vode (1 g/cm³): led 92 %, hrast 70 %, bor 50 %, pluto 24 %. Masa i veličina nisu važne: trupac od 500 kg pluta više nego blok leda od 50 kg, a kockici od 20 g pod vodom je veći dio nego ploči pluta od 2 kg.' } },

    /* ---------- MOTION / GIBANJE ---------- */
    { id: 't2-graph-height-vs-slope', topic: 'motion', type: 'mc', format: 'compare', level: 2,
      q: { en: 'A graph shows the distance from the school gate (s) against time (t) for two pupils walking along the same street; both lines are straight. Ana\'s line goes from 50 m at t = 0 to 60 m at t = 10 s. Marko\'s line goes from 0 m at t = 0 to 40 m at t = 10 s. Who is moving faster at t = 10 s?',
           hr: 'Graf prikazuje udaljenost od školskih vrata (s) u ovisnosti o vremenu (t) za dvoje učenika koji hodaju istom ulicom; obje su crte pravci. Anin pravac ide od 50 m u trenutku t = 0 do 60 m u trenutku t = 10 s. Markov pravac ide od 0 m u trenutku t = 0 do 40 m u trenutku t = 10 s. Tko se u trenutku t = 10 s giba brže?' },
      options: [ { en: 'Ana, because her line is higher on the graph', hr: 'Ana, jer je njezin pravac na grafu viši' }, { en: 'Marko, because his line is steeper', hr: 'Marko, jer je njegov pravac strmiji' }, { en: 'They are equally fast, because both lines are straight', hr: 'Jednako su brzi, jer su obje crte pravci' }, { en: 'It cannot be read from this graph', hr: 'To se iz ovoga grafa ne može očitati' } ],
      answer: 1,
      explain: { en: 'On such a graph the height of the line tells where the pupil is, and the slope tells how fast she or he moves. Ana covers 10 m in 10 s (1 m/s), Marko 40 m in 10 s (4 m/s). Ana is still ahead only because she started 50 m farther on; Marko will soon overtake her.',
                 hr: 'Na takvom grafu visina crte govori gdje se učenik nalazi, a nagib kako se brzo giba. Ana za 10 s prijeđe 10 m (1 m/s), a Marko 40 m (4 m/s). Ana je još uvijek ispred samo zato što je krenula 50 m dalje; Marko će je uskoro prestići.' },
      misconception: { en: 'A very common reading error is "the higher line is the faster one". Height shows position, slope shows speed.',
                       hr: 'Vrlo česta pogreška pri čitanju grafa je "viša crta je brža". Visina pokazuje položaj, a nagib brzinu.' } },

    { id: 't2-three-times-farther', topic: 'motion', type: 'mc', format: 'whatif', level: 1,
      q: { en: 'A cyclist rides along the Sava embankment at a steady speed and covers 2 km in 8 minutes. The same cyclist, at the same speed, rides a route three times as long (6 km). What happens to the riding time?',
           hr: 'Biciklistica vozi savskim nasipom stalnom brzinom i 2 km prijeđe za 8 minuta. Ista biciklistica istom brzinom vozi tri puta dulju dionicu (6 km). Što se događa s vremenom vožnje?' },
      options: [ { en: 'It is three times longer: 24 minutes', hr: 'Tri je puta dulje: 24 minute' }, { en: 'It is 4 minutes longer: 12 minutes', hr: 'Dulje je za 4 minute: 12 minuta' }, { en: 'It is twice as long: 16 minutes', hr: 'Dvostruko je dulje: 16 minuta' }, { en: 'It is nine times longer: 72 minutes', hr: 'Devet je puta dulje: 72 minute' } ],
      answer: 0,
      explain: { en: 'At a steady speed, distance and time are proportional: three times the distance takes three times the time, 3 · 8 min = 24 min. Check with the speed: 2 km / 8 min = 0.25 km/min, and 6 km / 0.25 km/min = 24 min.',
                 hr: 'Pri stalnoj brzini put i vrijeme su proporcionalni: za tri puta dulji put treba tri puta više vremena, 3 · 8 min = 24 min. Provjeri brzinom: 2 km / 8 min = 0,25 km/min, a 6 km / 0,25 km/min = 24 min.' },
      misconception: { en: 'The tempting mistake is to add instead of multiply: "4 km more, so 4 minutes more". Proportional quantities change by the same factor, not by the same amount.',
                       hr: 'Primamljiva je pogreška zbrajati umjesto množiti: "4 km više, dakle 4 minute više". Proporcionalne veličine mijenjaju se za isti faktor, a ne za isti iznos.' } },

    { id: 't2-rank-speeds-units', topic: 'motion', type: 'rank', level: 2,
      q: { en: 'Rank from the fastest to the slowest.', hr: 'Poredaj od najbržeg do najsporijeg.' },
      items: [ { en: 'a car driving through town at 50 km/h', hr: 'automobil koji gradom vozi 50 km/h' }, { en: 'a racing cyclist at 12 m/s', hr: 'biciklist na utrci brzinom 12 m/s' }, { en: 'a sprinter who runs 100 m in 10 s', hr: 'sprinter koji 100 m pretrči za 10 s' }, { en: 'a tram that covers 300 m in one minute', hr: 'tramvaj koji u jednoj minuti prijeđe 300 m' } ],
      explain: { en: 'Convert everything to m/s (divide km/h by 3.6): the car 50 km/h ≈ 13.9 m/s, the cyclist 12 m/s, the sprinter 100 m / 10 s = 10 m/s, the tram 300 m / 60 s = 5 m/s. You can compare speeds only when they are in the same unit.',
                 hr: 'Sve pretvori u m/s (km/h podijeli s 3,6): automobil 50 km/h ≈ 13,9 m/s, biciklist 12 m/s, sprinter 100 m / 10 s = 10 m/s, tramvaj 300 m / 60 s = 5 m/s. Brzine možeš uspoređivati tek kad su u istoj jedinici.' } },

    { id: 't2-estimate-crossing-street', topic: 'motion', type: 'num', level: 1,
      q: { en: 'Estimate how many seconds you need to cross a street 12 m wide at a normal walking pace.',
           hr: 'Procijeni koliko ti sekundi treba da normalnim hodom prijeđeš ulicu široku 12 m.' },
      answer: 9, min: 7, max: 12, unit: 's',
      explain: { en: 'A normal walking speed is about 1.2 to 1.5 m/s (4 to 5 km/h). t = s / v = 12 m / 1.3 m/s ≈ 9 s. In that time a car at 50 km/h travels about 125 m, so look far down the road before you step off the kerb.',
                 hr: 'Normalna brzina hoda je oko 1,2 do 1,5 m/s (4 do 5 km/h). t = s / v = 12 m / 1,3 m/s ≈ 9 s. Za to vrijeme automobil pri 50 km/h prijeđe oko 125 m, zato pogledaj daleko niz cestu prije nego što zakoračiš na kolnik.' } },

    /* ---------- FORCES / SILE ---------- */
    { id: 't2-puck-on-ice', topic: 'forces', type: 'mc', format: 'contentions', level: 2,
      q: { en: 'A hockey player hits a puck. The puck slides in a straight line across smooth ice long after it has left the stick. Ana says: "The force of the hit travels with the puck and keeps pushing it." Marko says: "Nothing pushes it forward any more. It keeps moving by itself, and the small friction only slows it down a little." Iva says: "Gravity pushes it forward along the ice." Who is right?',
           hr: 'Hokejaš udari pak. Pak klizi ravno po glatkom ledu još dugo nakon što se odvojio od palice. Ana kaže: "Sila udarca putuje s pakom i dalje ga gura." Marko kaže: "Naprijed ga više ništa ne gura. Giba se sam od sebe, a malo trenje samo ga pomalo usporava." Iva kaže: "Sila teža gura ga naprijed po ledu." Tko ima pravo?' },
      options: [ { en: 'Ana', hr: 'Ana' }, { en: 'Marko', hr: 'Marko' }, { en: 'Iva', hr: 'Iva' }, { en: 'none of them', hr: 'nitko od njih' } ],
      answer: 1,
      explain: { en: 'A force acts only while two bodies interact: when the puck leaves the stick, the force of the stick is over. A moving body keeps moving in a straight line at a steady speed until a force changes that (Newton\'s first law, inertia). On ice friction is very small, so the puck slides far; gravity pulls straight down and is balanced by the push of the ice.',
                 hr: 'Sila djeluje samo dok dva tijela međudjeluju: kad se pak odvoji od palice, sile palice više nema. Tijelo koje se giba nastavlja se gibati pravocrtno stalnom brzinom dok to neka sila ne promijeni (prvi Newtonov zakon, tromost). Na ledu je trenje vrlo malo, pa pak klizi daleko; sila teža vuče ravno prema dolje i uravnotežena je silom kojom led gura pak prema gore.' },
      misconception: { en: 'The idea that a hit "puts a force into" the body, which is then slowly used up, is very common. What the puck keeps is its motion, not a stored force.',
                       hr: 'Vrlo je česta ideja da udarac "stavi silu u" tijelo, koja se zatim polako troši. Pak zadržava gibanje, a ne spremljenu silu.' } },

    { id: 't2-bumper-cars-equal-forces', topic: 'forces', type: 'mc', format: 'compare', level: 2,
      q: { en: 'At a funfair two bumper cars collide head-on: one with an adult (200 kg in total) and one with a child (100 kg in total). During the collision, compare the force of the heavier car on the lighter car with the force of the lighter car on the heavier car.',
           hr: 'U lunaparku se čeono sudare dva električna autića: jedan s odraslom osobom (ukupno 200 kg) i jedan s djetetom (ukupno 100 kg). Usporedi silu kojom tijekom sudara teži autić djeluje na lakši sa silom kojom lakši djeluje na teži.' },
      options: [ { en: 'The heavier car pushes harder', hr: 'Teži autić djeluje većom silom' }, { en: 'The lighter car pushes harder', hr: 'Lakši autić djeluje većom silom' }, { en: 'The forces are equally big; the lighter car just changes its speed more', hr: 'Sile su jednako velike; lakšem se autiću samo više promijeni brzina' }, { en: 'It depends on which car was faster', hr: 'Ovisi o tome koji je autić bio brži' } ],
      answer: 2,
      explain: { en: 'A collision is one interaction, and the two forces of an interaction are always equal in size and opposite in direction (Newton\'s third law), whatever the masses and speeds. The same force changes the speed of the 100 kg car twice as much as that of the 200 kg car, because a = F / m. That is why the child is thrown back harder.',
                 hr: 'Sudar je jedno međudjelovanje, a dvije sile međudjelovanja uvijek su jednakog iznosa i suprotnog smjera (treći Newtonov zakon), bez obzira na mase i brzine. Ista sila autiću od 100 kg promijeni brzinu dvostruko više nego autiću od 200 kg, jer je a = F / m. Zato je dijete jače odbačeno unatrag.' },
      misconception: { en: '"The bigger or faster body hits harder" mixes up the force, which is the same on both, with its effect, which is bigger on the smaller mass.',
                       hr: '"Veće ili brže tijelo udara jače" miješa silu, koja je na oba tijela jednaka, s njezinim učinkom, koji je veći na tijelu manje mase.' } },

    { id: 't2-friction-brick-on-side', topic: 'forces', type: 'mc', format: 'whatif', level: 2,
      q: { en: 'With a dynamometer you pull a brick across a table at a steady speed. The brick lies on its largest face and the dynamometer shows 6 N. Now the same brick, on the same table, is turned onto its narrow side and pulled at a steady speed again. What does the dynamometer show?',
           hr: 'Dinamometrom vučeš ciglu po stolu stalnom brzinom. Cigla leži na najvećoj plohi i dinamometar pokazuje 6 N. Sada istu ciglu na istom stolu okreneš na usku bočnu plohu i opet je vučeš stalnom brzinom. Što pokazuje dinamometar?' },
      options: [ { en: 'About 6 N, the same as before', hr: 'Oko 6 N, jednako kao prije' }, { en: 'Less than 6 N, because the contact area is smaller', hr: 'Manje od 6 N, jer je dodirna površina manja' }, { en: 'More than 6 N, because the brick digs into the table more', hr: 'Više od 6 N, jer se cigla jače utiskuje u stol' }, { en: 'It cannot be predicted without knowing the area', hr: 'Ne može se predvidjeti bez poznavanja površine' } ],
      answer: 0,
      explain: { en: 'Sliding friction depends on how hard the two surfaces are pressed together (here the weight of the brick) and on what the surfaces are made of, but practically not on the size of the contact area. On the narrow side the area is smaller, but every square centimetre is pressed harder, and the two effects cancel. Because the speed is steady, the pull equals the friction, about 6 N in both cases.',
                 hr: 'Trenje klizanja ovisi o tome kolikom su silom dvije plohe pritisnute jedna uz drugu (ovdje je to težina cigle) i o vrsti ploha, ali praktički ne ovisi o veličini dodirne površine. Na uskoj plohi površina je manja, ali je svaki kvadratni centimetar jače pritisnut, pa se ta dva učinka ponište. Budući da je brzina stalna, vučna sila jednaka je trenju, u oba slučaja oko 6 N.' },
      misconception: { en: '"A bigger contact area gives more friction" seems obvious, but for dry solid surfaces it is not true. Friction grows with the pressing force and changes with the materials, not with the area.',
                       hr: '"Veća dodirna površina daje veće trenje" čini se očitim, ali za suhe čvrste plohe to ne vrijedi. Trenje raste s pritisnom silom i mijenja se s vrstom materijala, a ne s površinom.' } },

    { id: 't2-rank-resultant-force', topic: 'forces', type: 'rank', level: 1,
      q: { en: 'Two forces act on a cart along the same line. Rank the cases from the largest resultant force to the smallest.',
           hr: 'Na kolica duž istog pravca djeluju dvije sile. Poredaj slučajeve od najveće rezultantne sile do najmanje.' },
      items: [ { en: '15 N to the right and 15 N to the right', hr: '15 N udesno i 15 N udesno' }, { en: '30 N to the right and 10 N to the left', hr: '30 N udesno i 10 N ulijevo' }, { en: '50 N to the right and 38 N to the left', hr: '50 N udesno i 38 N ulijevo' }, { en: '40 N to the right and 35 N to the left', hr: '40 N udesno i 35 N ulijevo' } ],
      explain: { en: 'Forces in the same direction add up and forces in opposite directions subtract: 30 N, 20 N, 12 N and 5 N. Large forces can give a small resultant if they nearly cancel, as 40 N and 35 N do.',
                 hr: 'Sile istog smjera se zbrajaju, a sile suprotnog smjera oduzimaju: 30 N, 20 N, 12 N i 5 N. Velike sile mogu dati malu rezultantu ako se gotovo ponište, kao 40 N i 35 N.' } },

    { id: 't2-spring-stretch-proportion', topic: 'forces', type: 'num', level: 2,
      q: { en: 'A spring gets 4 cm longer when a 2 N weight hangs on it. How many centimetres longer than its unloaded length is it when a 5 N weight hangs on it? (The spring is not overstretched.)',
           hr: 'Opruga se produlji za 4 cm kad na nju objesimo uteg težine 2 N. Za koliko je centimetara dulja od neopterećene opruge kad na njoj visi uteg težine 5 N? (Opruga nije previše rastegnuta.)' },
      answer: 10, min: 9.5, max: 10.5, unit: 'cm',
      explain: { en: 'The extension of a spring is proportional to the force: every newton stretches this spring by 2 cm, so 5 N stretches it by 5 · 2 cm = 10 cm. A dynamometer works this way: equal steps of force give equal steps on its scale.',
                 hr: 'Produljenje opruge proporcionalno je sili: svaki njutn produlji ovu oprugu za 2 cm, pa je 5 N produlji za 5 · 2 cm = 10 cm. Tako radi dinamometar: jednaki koraci sile daju jednake korake na ljestvici.' } },

    /* ---------- GRAVITY / GRAVITACIJA ---------- */
    { id: 't2-twice-heavier-stone', topic: 'gravity', type: 'mc', format: 'troubleshoot', level: 2,
      q: { en: 'Luka explains why he thinks a 2 kg stone falls faster than a 1 kg stone (air resistance is ignored). Step 1: "Earth pulls the 2 kg stone with twice the force." Step 2: "Twice the force gives twice the acceleration." Step 3: "So the heavier stone hits the ground first." Where is the first mistake?',
           hr: 'Luka objašnjava zašto misli da kamen mase 2 kg pada brže od kamena mase 1 kg (otpor zraka zanemarujemo). Prvi korak: "Zemlja kamen od 2 kg privlači dvostruko većom silom." Drugi korak: "Dvostruko veća sila daje dvostruko veće ubrzanje." Treći korak: "Zato teži kamen prvi udari o tlo." Gdje je prva pogreška?' },
      options: [ { en: 'In step 1: Earth pulls both stones with the same force', hr: 'U prvom koraku: Zemlja oba kamena privlači jednakom silom' }, { en: 'In step 2: twice the force acts on twice the mass, so the acceleration is the same', hr: 'U drugom koraku: dvostruko veća sila djeluje na dvostruko veću masu, pa je ubrzanje jednako' }, { en: 'Only in step 3: the lighter stone lands first', hr: 'Tek u trećem koraku: prvi padne lakši kamen' }, { en: 'There is no mistake; heavier stones do fall faster', hr: 'Nema pogreške; teže kamenje doista pada brže' } ],
      answer: 1,
      explain: { en: 'Step 1 is correct: weight is G = m · g, so 20 N and 10 N. But acceleration is a = F / m: 20 N / 2 kg = 10 N / 1 kg = 10 m/s². Twice the pull has to speed up twice the mass, so both stones gain speed at the same rate and land together.',
                 hr: 'Prvi je korak točan: težina je G = m · g, dakle 20 N i 10 N. No ubrzanje je a = F / m: 20 N / 2 kg = 10 N / 1 kg = 10 m/s². Dvostruko veća sila mora ubrzati dvostruko veću masu, pa oba kamena jednako dobivaju brzinu i padnu istodobno.' },
      misconception: { en: '"A bigger force means a faster fall" forgets that a bigger mass is also harder to speed up. The opposite mistake, that gravity pulls all bodies with the same force, is just as common.',
                       hr: '"Veća sila znači brži pad" zaboravlja da je veću masu i teže ubrzati. Jednako je česta i suprotna pogreška, da sila teža sva tijela privlači jednakom silom.' } },

    { id: 't2-astronauts-float-iss', topic: 'gravity', type: 'mc', format: 'contentions', level: 2,
      q: { en: 'Astronauts float inside the International Space Station, which circles Earth about 400 km above the ground. Ana says: "There is no gravity that high up." Marko says: "Gravity there is almost as strong as on the ground. They float because the station and the astronauts are falling around Earth together." Iva says: "There is gravity, but without air it cannot act." Who is right?',
           hr: 'Astronauti lebde u Međunarodnoj svemirskoj postaji, koja kruži oko Zemlje na visini od oko 400 km. Ana kaže: "Tako visoko nema gravitacije." Marko kaže: "Gravitacija je ondje gotovo jednako jaka kao na tlu. Lebde zato što postaja i astronauti zajedno padaju oko Zemlje." Iva kaže: "Gravitacije ima, ali bez zraka ne može djelovati." Tko ima pravo?' },
      options: [ { en: 'Ana', hr: 'Ana' }, { en: 'Marko', hr: 'Marko' }, { en: 'Iva', hr: 'Iva' }, { en: 'none of them', hr: 'nitko od njih' } ],
      answer: 1,
      explain: { en: 'At a height of 400 km gravity is still about 90 % as strong as on the ground, and it is exactly what keeps the station in its orbit. The station moves sideways so fast (about 28 000 km/h) that, while falling, it keeps missing Earth. Everything inside falls in the same way, so nothing presses on the floor and the astronauts feel weightless.',
                 hr: 'Na visini od 400 km gravitacija je još uvijek oko 90 % one na tlu i upravo ona drži postaju na njezinoj putanji. Postaja se giba bočno tako brzo (oko 28 000 km/h) da padajući stalno promašuje Zemlju. Sve u njoj pada na isti način, pa ništa ne pritišće pod i astronauti su u bestežinskom stanju.' },
      misconception: { en: '"There is no gravity in space" is a very common belief; pupils often tie gravity to air. Gravity gets weaker with distance but never ends: it holds the Moon in its orbit too.',
                       hr: '"U svemiru nema gravitacije" vrlo je često uvjerenje; učenici gravitaciju često povezuju sa zrakom. Gravitacija slabi s udaljenošću, ali nigdje ne prestaje: ona i Mjesec drži na putanji.' } },

    /* ---------- PRESSURE / TLAK ---------- */
    { id: 't2-drawing-pin-force-pressure', topic: 'pressure', type: 'mc', format: 'compare', level: 2,
      q: { en: 'Imagine you gently squeeze a drawing pin between two fingers and hold it still: the thumb on the flat head, the forefinger on the sharp point. Compare the forces and the pressures on the two fingers.',
           hr: 'Zamisli da risaći čavlić lagano stisneš između dva prsta i držiš ga mirno: palac na plosnatoj glavici, kažiprst na oštrom šiljku. Usporedi sile i tlakove na ta dva prsta.' },
      options: [ { en: 'The force on the forefinger is bigger; the pressures are equal', hr: 'Sila na kažiprst je veća; tlakovi su jednaki' }, { en: 'The forces are equal, but the pressure on the forefinger is much bigger', hr: 'Sile su jednake, ali je tlak na kažiprst mnogo veći' }, { en: 'Both the force and the pressure are bigger on the forefinger', hr: 'Na kažiprst su veći i sila i tlak' }, { en: 'The forces are equal and the pressures are equal', hr: 'Jednake su i sile i tlakovi' } ],
      answer: 1,
      explain: { en: 'The pin is at rest, so the two fingers push on it with equal forces, and it pushes back on each finger with that same force. Pressure is force divided by area, p = F / A. The point has an area hundreds of times smaller than the head, so the pressure there is hundreds of times bigger, and that is what hurts.',
                 hr: 'Čavlić miruje, pa ga oba prsta guraju jednakim silama, a on svaki prst gura natrag tom istom silom. Tlak je sila podijeljena s površinom, p = F / A. Šiljak ima stotinama puta manju površinu od glavice, pa je tlak ondje stotinama puta veći, i upravo to boli.' },
      misconception: { en: 'Pupils often use "force" and "pressure" as the same word: "it hurts more, so the force is bigger". The same force can produce very different pressures.',
                       hr: 'Učenici često riječi "sila" i "tlak" koriste kao da znače isto: "više boli, dakle sila je veća". Ista sila može stvoriti vrlo različite tlakove.' } },

    { id: 't2-depth-for-extra-atmosphere', topic: 'pressure', type: 'num', level: 2,
      q: { en: 'Air pressure at sea level is about 100 kPa. How deep, in metres, must a diver go in a lake so that the water alone adds another 100 kPa? (Density of water 1000 kg/m³, g = 10 N/kg.)',
           hr: 'Tlak zraka na razini mora iznosi oko 100 kPa. Koliko duboko, u metrima, ronilac mora zaroniti u jezero da sama voda doda još 100 kPa? (Gustoća vode 1000 kg/m³, g = 10 N/kg.)' },
      answer: 10, min: 9.5, max: 10.5, unit: 'm',
      explain: { en: 'p = ρ · g · h, so h = p / (ρ · g) = 100 000 Pa / (1000 kg/m³ · 10 N/kg) = 10 m. Just 10 m of water presses as hard as the whole atmosphere, which is many kilometres thick, because water is about 800 times denser than air. At a depth of 10 m the total pressure on the diver is therefore about 200 kPa.',
                 hr: 'p = ρ · g · h, pa je h = p / (ρ · g) = 100 000 Pa / (1000 kg/m³ · 10 N/kg) = 10 m. Samo 10 m vode tlači jednako kao cijela atmosfera, debela mnogo kilometara, jer je voda oko 800 puta gušća od zraka. Na dubini od 10 m ukupni je tlak na ronioca zato oko 200 kPa.' } },

    /* ---------- LEVERS / POLUGE ---------- */
    { id: 't2-rank-turning-effect', topic: 'levers', type: 'rank', level: 2,
      q: { en: 'Four pupils push on a spanner at right angles to it, each trying to loosen the same nut. Rank from the largest turning effect (moment of force) to the smallest.',
           hr: 'Četvero učenika gura ključ okomito na njegovu dršku, pokušavajući odviti istu maticu. Poredaj od najvećeg momenta sile (zakretnog učinka) do najmanjeg.' },
      items: [ { en: '20 N at 30 cm from the nut', hr: '20 N na udaljenosti 30 cm od matice' }, { en: '50 N at 10 cm from the nut', hr: '50 N na udaljenosti 10 cm od matice' }, { en: '10 N at 40 cm from the nut', hr: '10 N na udaljenosti 40 cm od matice' }, { en: '30 N at 5 cm from the nut', hr: '30 N na udaljenosti 5 cm od matice' } ],
      explain: { en: 'Moment of force = force × arm: 20 N · 0.3 m = 6 N·m, 50 N · 0.1 m = 5 N·m, 10 N · 0.4 m = 4 N·m and 30 N · 0.05 m = 1.5 N·m. The largest force (50 N) does not win, because it acts on a short arm; a small force far from the nut can turn it better.',
                 hr: 'Moment sile = sila × krak: 20 N · 0,3 m = 6 N·m, 50 N · 0,1 m = 5 N·m, 10 N · 0,4 m = 4 N·m i 30 N · 0,05 m = 1,5 N·m. Najveća sila (50 N) ne pobjeđuje, jer djeluje na kratkom kraku; mala sila daleko od matice može je bolje zakrenuti.' } },

    { id: 't2-ruler-balance-eraser', topic: 'levers', type: 'num', level: 2,
      q: { en: 'A 30 cm ruler is balanced at its middle on the edge of a pencil. You put a 60 g eraser on it, 4 cm from the middle. How many centimetres from the middle, on the other side, must you put a 20 g pencil sharpener so that the ruler balances again?',
           hr: 'Ravnalo dugo 30 cm uravnoteženo je u svojoj sredini na bridu olovke. Na njega staviš gumicu mase 60 g, 4 cm od sredine. Koliko centimetara od sredine, s druge strane, moraš staviti šiljilo mase 20 g da ravnalo opet bude u ravnoteži?' },
      answer: 12, min: 11.5, max: 12.5, unit: 'cm',
      explain: { en: 'A lever balances when force × arm is the same on both sides, and since weight is proportional to mass we can compare mass × distance: 60 g · 4 cm = 20 g · x, so x = 12 cm. The sharpener is three times lighter, so it must lie three times farther from the support. Try it on your desk.',
                 hr: 'Poluga je u ravnoteži kad je umnožak sile i kraka jednak na obje strane, a kako je težina proporcionalna masi, možemo uspoređivati umnožak mase i udaljenosti: 60 g · 4 cm = 20 g · x, pa je x = 12 cm. Šiljilo je tri puta lakše, pa mora ležati tri puta dalje od oslonca. Isprobaj na svojoj klupi.' } },

    /* ---------- ENERGY / ENERGIJA ---------- */
    { id: 't2-pushing-wall-work', topic: 'energy', type: 'mc', format: 'troubleshoot', level: 2,
      q: { en: 'Fran pushes against the school wall with a force of 200 N for 30 s. The wall does not move. In his notebook he writes: "W = 200 N · 30 s = 6000 J." Where is the mistake?',
           hr: 'Fran 30 s gura zid škole silom 200 N. Zid se ne pomiče. U bilježnicu zapiše: "W = 200 N · 30 s = 6000 J." Gdje je pogreška?' },
      options: [ { en: 'Work is force times the distance moved, not force times time; the wall did not move, so the work done on it is 0 J', hr: 'Rad je umnožak sile i prijeđenog puta, a ne sile i vremena; zid se nije pomaknuo, pa je rad obavljen na njemu 0 J' }, { en: 'He should have divided: 200 N / 30 s', hr: 'Trebao je dijeliti: 200 N / 30 s' }, { en: 'The number is right, only the unit should be W instead of J', hr: 'Broj je točan, samo jedinica treba biti W umjesto J' }, { en: 'There is no mistake: he got tired, so he did work on the wall', hr: 'Nema pogreške: umorio se, dakle obavio je rad na zidu' } ],
      answer: 0,
      explain: { en: 'In physics work is done only when a force moves a body: W = F · s. Here s = 0, so the work done on the wall is 0 J, however long Fran pushes. His muscles do use energy from food and turn it into heat, which is why he gets tired, but no energy passes to the wall.',
                 hr: 'U fizici se rad obavlja samo kad sila pomiče tijelo: W = F · s. Ovdje je s = 0, pa je rad obavljen na zidu 0 J, koliko god dugo Fran gurao. Njegovi mišići pritom troše energiju iz hrane i pretvaraju je u toplinu, zato se umori, ali na zid ne prelazi nikakva energija.' },
      misconception: { en: 'In everyday speech "work" means effort or time spent. In physics work measures the energy passed to a body by a force along a distance.',
                       hr: 'U svakodnevnom govoru "rad" znači trud ili utrošeno vrijeme. U fizici rad mjeri energiju koju sila na nekom putu preda tijelu.' } },

    { id: 't2-barchart-slide-friction', topic: 'energy', type: 'mc', format: 'barchart', level: 2,
      q: { en: 'An energy bar chart for a child on a playground slide. At the top the bars are: kinetic energy 0 squares, gravitational potential energy 6 squares. At the bottom: kinetic energy 4 squares, potential energy 0 squares. What must be added to the chart at the bottom to make it complete?',
           hr: 'Stupčasti dijagram energije za dijete na toboganu. Na vrhu su stupci: kinetička energija 0 kvadratića, gravitacijska potencijalna energija 6 kvadratića. Na dnu: kinetička energija 4 kvadratića, potencijalna energija 0 kvadratića. Što treba dodati dijagramu na dnu da bude potpun?' },
      options: [ { en: 'Nothing: 2 squares of energy were used up and no longer exist', hr: 'Ništa: 2 kvadratića energije su se potrošila i više ne postoje' }, { en: 'A bar of 2 squares for internal (thermal) energy: friction warmed the slide and the clothes', hr: 'Stupac od 2 kvadratića za unutarnju (toplinsku) energiju: trenje je zagrijalo tobogan i odjeću' }, { en: 'A bar of 2 squares of potential energy', hr: 'Stupac od 2 kvadratića potencijalne energije' }, { en: 'Two more squares on the kinetic energy bar', hr: 'Još 2 kvadratića na stupcu kinetičke energije' } ],
      answer: 1,
      explain: { en: 'Energy is conserved: the bars must add up to 6 squares both at the top and at the bottom. The kinetic energy is 4 squares, so the other 2 squares have become internal energy of the slide, the clothes and the air, because of friction. That is why a slide feels warm after a fast ride.',
                 hr: 'Energija je očuvana: zbroj stupaca mora biti 6 kvadratića i na vrhu i na dnu. Kinetička energija iznosi 4 kvadratića, pa su preostala 2 kvadratića zbog trenja postala unutarnja energija tobogana, odjeće i zraka. Zato je tobogan nakon brzog spuštanja topao.' },
      misconception: { en: '"Energy gets used up." Energy never disappears; it changes into forms that are less useful and harder to notice, mostly internal energy of the surroundings.',
                       hr: '"Energija se potroši." Energija nikad ne nestaje; prelazi u oblike koji su manje korisni i teže ih je opaziti, najčešće u unutarnju energiju okoline.' } },

    { id: 't2-jeopardy-mass-g-height', topic: 'energy', type: 'mc', format: 'jeopardy', level: 2,
      q: { en: 'Someone wrote this calculation: ? = 60 kg · 10 N/kg · 3 m. Which situation does it describe?',
           hr: 'Netko je zapisao ovaj račun: ? = 60 kg · 10 N/kg · 3 m. Koju situaciju on opisuje?' },
      options: [ { en: 'How much gravitational potential energy a 60 kg pupil gains by climbing to a diving platform 3 m high', hr: 'Koliko gravitacijske potencijalne energije dobije učenik mase 60 kg kad se popne na skakaonicu visoku 3 m' }, { en: 'The kinetic energy of a 60 kg pupil running at 3 m/s', hr: 'Kinetičku energiju učenika mase 60 kg koji trči brzinom 3 m/s' }, { en: 'The weight of a 60 kg pupil standing 3 m from a wall', hr: 'Težinu učenika mase 60 kg koji stoji 3 m od zida' }, { en: 'The power of a 60 kg pupil who climbs stairs for 3 s', hr: 'Snagu učenika mase 60 kg koji se 3 s penje stubama' } ],
      answer: 0,
      explain: { en: '60 kg · 10 N/kg is the weight, 600 N. Multiplied by a height of 3 m it gives the work done against gravity, which is the gain in potential energy: Ep = m · g · h = 1800 J. The units decide: kg · N/kg · m = N · m = J, an energy, not a force (N) or a power (W).',
                 hr: '60 kg · 10 N/kg je težina, 600 N. Pomnožena s visinom 3 m daje rad protiv sile teže, a to je dobivena potencijalna energija: Ep = m · g · h = 1800 J. Odlučuju jedinice: kg · N/kg · m = N · m = J, dakle energija, a ne sila (N) ni snaga (W).' },
      misconception: { en: 'It is tempting to pick a situation just because the same numbers appear in it. Look at the units: kinetic energy would need m/s, and power would need seconds.',
                       hr: 'Primamljivo je odabrati situaciju samo zato što se u njoj pojavljuju isti brojevi. Pogledaj jedinice: za kinetičku energiju trebali bi m/s, a za snagu sekunde.' } },

    { id: 't2-rank-appliance-energy', topic: 'energy', type: 'rank', level: 2,
      q: { en: 'Rank from the most electrical energy used to the least.', hr: 'Poredaj od najviše utrošene električne energije do najmanje.' },
      items: [ { en: 'an oven of 2000 W, on for 1.5 h', hr: 'pećnica snage 2000 W, uključena 1,5 h' }, { en: 'a television of 100 W, on for 5 h', hr: 'televizor snage 100 W, uključen 5 h' }, { en: 'an LED bulb of 10 W, on for 20 h', hr: 'LED žarulja snage 10 W, uključena 20 h' }, { en: 'a kettle of 2000 W, on for 3 min', hr: 'kuhalo za vodu snage 2000 W, uključeno 3 min' } ],
      explain: { en: 'Energy = power × time: the oven 2 kW · 1.5 h = 3 kWh, the television 0.1 kW · 5 h = 0.5 kWh, the LED bulb 0.01 kW · 20 h = 0.2 kWh, the kettle 2 kW · 0.05 h = 0.1 kWh. Power tells how fast energy is used, not how much: the powerful kettle uses the least, because it works for only a short time.',
                 hr: 'Energija = snaga × vrijeme: pećnica 2 kW · 1,5 h = 3 kWh, televizor 0,1 kW · 5 h = 0,5 kWh, LED žarulja 0,01 kW · 20 h = 0,2 kWh, kuhalo 2 kW · 0,05 h = 0,1 kWh. Snaga govori kako se brzo energija troši, a ne koliko je se potroši: snažno kuhalo potroši najmanje, jer radi samo kratko.' } },

    { id: 't2-estimate-sljeme-climb-energy', topic: 'energy', type: 'num', level: 2,
      q: { en: 'Estimate, in kJ, how much gravitational potential energy a 50 kg hiker gains by walking from the foot of Medvednica up to the top of Sljeme, a height difference of about 750 m. Use g = 10 N/kg.',
           hr: 'Procijeni, u kJ, koliko gravitacijske potencijalne energije dobije planinar mase 50 kg kad se od podnožja Medvednice popne na vrh Sljemena, uz visinsku razliku od oko 750 m. Uzmi g = 10 N/kg.' },
      answer: 375, min: 350, max: 400, unit: 'kJ',
      explain: { en: 'Ep = m · g · h = 50 kg · 10 N/kg · 750 m = 375 000 J = 375 kJ. That is surprisingly little: a 100 g bar of chocolate holds about 2200 kJ. The body, however, turns only about a quarter of the energy from food into such work; the rest becomes heat, which is why you sweat on the way up.',
                 hr: 'Ep = m · g · h = 50 kg · 10 N/kg · 750 m = 375 000 J = 375 kJ. To je iznenađujuće malo: čokolada od 100 g sadrži oko 2200 kJ. Tijelo, međutim, samo oko četvrtinu energije iz hrane pretvara u takav rad; ostatak postaje toplina, zato se pri usponu znojiš.' } },

    /* ---------- HEAT / TOPLINA ---------- */
    { id: 't2-tea-vs-bath', topic: 'heat', type: 'mc', format: 'compare', level: 2,
      q: { en: 'A cup of tea (0.2 kg of water at 80 °C) stands next to a full bathtub (150 kg of water at 40 °C). The room is at 20 °C. Compare them.',
           hr: 'Šalica čaja (0,2 kg vode temperature 80 °C) stoji pokraj pune kade (150 kg vode temperature 40 °C). U sobi je 20 °C. Usporedi ih.' },
      options: [ { en: 'The tea has the higher temperature, but the bath water gives off far more heat while cooling to room temperature', hr: 'Čaj ima višu temperaturu, ali voda u kadi pri hlađenju do sobne temperature preda mnogo više topline' }, { en: 'The tea has the higher temperature, so it also gives off more heat', hr: 'Čaj ima višu temperaturu, pa preda i više topline' }, { en: 'Both give off the same heat, because both are water', hr: 'Oboje preda jednaku toplinu, jer je oboje voda' }, { en: 'The bath water has the higher temperature, because there is more of it', hr: 'Voda u kadi ima višu temperaturu, jer je ima više' } ],
      answer: 0,
      explain: { en: 'Temperature tells how hot something is; heat is the energy that passes because of a temperature difference, and it also depends on the mass: Q = m · c · ΔT. Tea: 0.2 kg · 4200 J/(kg·°C) · 60 °C ≈ 50 kJ. Bath: 150 kg · 4200 J/(kg·°C) · 20 °C = 12 600 kJ, about 250 times more.',
                 hr: 'Temperatura govori koliko je nešto toplo; toplina je energija koja prelazi zbog razlike temperatura, a ovisi i o masi: Q = m · c · ΔT. Čaj: 0,2 kg · 4200 J/(kg·°C) · 60 °C ≈ 50 kJ. Kada: 150 kg · 4200 J/(kg·°C) · 20 °C = 12 600 kJ, oko 250 puta više.' },
      misconception: { en: '"Hotter means more heat." Temperature and heat are different quantities: a spark from a sparkler is hotter than 1000 °C, but it carries so little energy that it does not burn your hand.',
                       hr: '"Toplije znači više topline." Temperatura i toplina različite su veličine: iskra prskalice toplija je od 1000 °C, ali nosi tako malo energije da ti ne opeče ruku.' } },

    { id: 't2-ice-cube-cold-flows', topic: 'heat', type: 'mc', format: 'contentions', level: 1,
      q: { en: 'You hold an ice cube in your hand and your hand gets cold. Ana says: "Cold flows from the ice into my hand." Marko says: "Heat flows from my hand into the ice, and my hand cools because it loses energy." Petra says: "Both happen: cold goes into the hand and heat goes into the ice." Who is right?',
           hr: 'Držiš kockicu leda u ruci i ruka ti se hladi. Ana kaže: "Hladnoća prelazi s leda na moju ruku." Marko kaže: "Toplina prelazi s moje ruke na led, a ruka se hladi jer gubi energiju." Petra kaže: "Događa se oboje: hladnoća ulazi u ruku, a toplina u led." Tko ima pravo?' },
      options: [ { en: 'Ana', hr: 'Ana' }, { en: 'Marko', hr: 'Marko' }, { en: 'Petra', hr: 'Petra' }, { en: 'none of them', hr: 'nitko od njih' } ],
      answer: 1,
      explain: { en: 'Only one thing passes between the bodies: energy, as heat, and always from the warmer body to the colder one. "Cold" is not a substance; it is only a lack of that energy. Your hand loses energy and cools, while the ice gains it and melts.',
                 hr: 'Između tijela prelazi samo jedno: energija, u obliku topline, i to uvijek s toplijeg tijela na hladnije. "Hladnoća" nije tvar; ona je samo manjak te energije. Tvoja ruka gubi energiju i hladi se, a led je prima i tali se.' },
      misconception: { en: 'Many people treat "cold" as a second kind of stuff that moves by itself ("shut the door, the cold is coming in"). Physics needs only heat, passing from warmer to colder.',
                       hr: 'Mnogi "hladnoću" zamišljaju kao drugu vrstu tvari koja se sama giba ("zatvori vrata, ulazi hladnoća"). Fizici je dovoljna toplina, koja prelazi s toplijeg na hladnije.' } },

    { id: 't2-boiling-stays-100', topic: 'heat', type: 'mc', format: 'whatif', level: 2,
      q: { en: 'Water boils gently in a pot on the stove at 100 °C (normal air pressure). You turn the hob up to its strongest setting. What happens to the temperature of the boiling water?',
           hr: 'Voda u loncu na štednjaku lagano vrije pri 100 °C (normalan tlak zraka). Pojačaš ploču na najjače. Što se događa s temperaturom kipuće vode?' },
      options: [ { en: 'It stays at about 100 °C; the water only boils away faster', hr: 'Ostaje oko 100 °C; voda samo brže isparava' }, { en: 'It keeps rising above 100 °C as long as the hob is on', hr: 'Stalno raste iznad 100 °C dok je ploča uključena' }, { en: 'It rises to a new, higher boiling temperature and stays there', hr: 'Poraste do nove, više temperature vrenja i ondje ostane' }, { en: 'It falls, because the steam carries the heat away', hr: 'Padne, jer para odnosi toplinu' } ],
      answer: 0,
      explain: { en: 'While water boils, the energy it receives is used to turn liquid into steam, that is, to pull the molecules apart, and not to raise the temperature. Stronger heating gives more steam every second, but the thermometer stays at 100 °C until all the water is gone. That is why pasta does not cook faster on full power once the water is boiling.',
                 hr: 'Dok voda vrije, energija koju prima troši se na pretvaranje tekućine u paru, to jest na razdvajanje molekula, a ne na povišenje temperature. Jače grijanje daje više pare svake sekunde, ali termometar ostaje na 100 °C sve dok sva voda ne ispari. Zato se tjestenina ne kuha brže na najjačoj ploči kad voda već vrije.' },
      misconception: { en: '"More heating always means a higher temperature." During a change of state the temperature stays the same although energy keeps coming in.',
                       hr: '"Jače grijanje uvijek znači višu temperaturu." Tijekom promjene agregacijskog stanja temperatura ostaje ista iako energija i dalje pristiže.' } },

    { id: 't2-rank-heat-to-warm-water', topic: 'heat', type: 'rank', level: 2,
      q: { en: 'Rank from the most heat needed to the least. All four are water.', hr: 'Poredaj od najviše potrebne topline do najmanje. U sva četiri slučaja riječ je o vodi.' },
      items: [ { en: '1 kg of water warmed by 30 °C', hr: '1 kg vode zagrijavamo za 30 °C' }, { en: '2 kg of water warmed by 10 °C', hr: '2 kg vode zagrijavamo za 10 °C' }, { en: '3 kg of water warmed by 5 °C', hr: '3 kg vode zagrijavamo za 5 °C' }, { en: '0.5 kg of water warmed by 20 °C', hr: '0,5 kg vode zagrijavamo za 20 °C' } ],
      explain: { en: 'Q = m · c · ΔT and c is the same for all of them, so it is enough to compare m · ΔT: 30, 20, 15 and 10 kg·°C. In joules: 126 kJ, 84 kJ, 63 kJ and 42 kJ. Neither the largest mass nor the largest temperature change decides alone; their product does.',
                 hr: 'Q = m · c · ΔT, a c je svima jednak, pa je dovoljno usporediti m · ΔT: 30, 20, 15 i 10 kg·°C. U džulima: 126 kJ, 84 kJ, 63 kJ i 42 kJ. Ne odlučuje ni najveća masa ni najveća promjena temperature sama za sebe, nego njihov umnožak.' } },

    { id: 't2-mixing-water-temperature', topic: 'heat', type: 'num', level: 2,
      q: { en: 'You pour 1 litre of water at 60 °C into 3 litres of water at 20 °C and stir. What is the final temperature, in °C? (Ignore heat losses to the surroundings.)',
           hr: 'U 3 litre vode temperature 20 °C uliješ 1 litru vode temperature 60 °C i promiješaš. Kolika je konačna temperatura, u °C? (Zanemari gubitke topline u okolinu.)' },
      answer: 30, min: 29, max: 31, unit: '°C',
      explain: { en: 'The warm water gives up exactly as much heat as the cold water takes in. There is three times more cold water, so its temperature changes three times less: it warms by 10 °C while the hot water cools by 30 °C, and they meet at 30 °C. Temperatures do not add up (80 °C is impossible), and the result is the simple middle (40 °C) only when the amounts are equal.',
                 hr: 'Topla voda preda točno onoliko topline koliko hladna primi. Hladne vode ima tri puta više, pa joj se temperatura promijeni tri puta manje: ona se zagrije za 10 °C, dok se vruća ohladi za 30 °C, i susretnu se na 30 °C. Temperature se ne zbrajaju (80 °C je nemoguće), a rezultat je točno na sredini (40 °C) samo kad su količine jednake.' } },

    /* ---------- ELECTRICITY / ELEKTRICITET ---------- */
    { id: 't2-second-bulb-parallel', topic: 'electricity', type: 'mc', format: 'whatif', level: 3,
      q: { en: 'One bulb is connected to a fresh battery, and an ammeter next to the battery shows 0.2 A. Now a second, identical bulb is connected in parallel with the first one. What does the ammeter next to the battery show?',
           hr: 'Jedna je žarulja spojena na novu bateriju, a ampermetar uz bateriju pokazuje 0,2 A. Sada paralelno prvoj žarulji spojimo drugu, jednaku žarulju. Što pokazuje ampermetar uz bateriju?' },
      options: [ { en: '0.2 A: a battery always gives the same current, and the bulbs share it', hr: '0,2 A: baterija uvijek daje jednaku struju, a žarulje je dijele' }, { en: '0.4 A: each bulb gets the full voltage and draws its own 0.2 A', hr: '0,4 A: svaka žarulja dobiva puni napon i kroz svaku teče 0,2 A' }, { en: '0.1 A: two bulbs are a bigger obstacle than one', hr: '0,1 A: dvije žarulje veća su prepreka nego jedna' } ],
      answer: 1,
      explain: { en: 'A battery sets the voltage, not the current. In a parallel connection each bulb is joined directly to the battery, gets the full voltage and carries 0.2 A, so the battery must supply 0.4 A. Both bulbs shine as brightly as one alone, but the battery runs down twice as fast.',
                 hr: 'Baterija određuje napon, a ne struju. U paralelnom spoju svaka je žarulja spojena izravno na bateriju, dobiva puni napon i kroz nju teče 0,2 A, pa baterija mora davati 0,4 A. Obje žarulje svijetle jednako jako kao jedna sama, ali se baterija prazni dvostruko brže.' },
      misconception: { en: 'Many pupils see the battery as a source of a fixed current that the bulbs have to share. The current depends on what is connected; what the battery keeps (almost) the same is the voltage.',
                       hr: 'Mnogi učenici bateriju vide kao izvor stalne struje koju žarulje moraju dijeliti. Struja ovisi o tome što je spojeno; baterija (gotovo) stalnim održava napon.' } },

    { id: 't2-short-circuit-wire', topic: 'electricity', type: 'mc', format: 'troubleshoot', level: 2,
      q: { en: 'Luka wants his bulb to shine brighter. The bulb stays connected to the battery, and he adds a thick copper wire that joins one contact of the bulb directly to the other. The bulb goes out, and the wire and the battery get hot. Where is the mistake?',
           hr: 'Luka želi da mu žarulja jače svijetli. Žarulja ostaje spojena na bateriju, a on doda debelu bakrenu žicu koja jedan kontakt žarulje izravno spaja s drugim. Žarulja se ugasi, a žica i baterija se zagriju. Gdje je pogreška?' },
      options: [ { en: 'The wire is a path with almost no resistance around the bulb, a short circuit: nearly all the current flows through the wire, and it is very large', hr: 'Žica je put gotovo bez otpora mimo žarulje, kratki spoj: gotovo sva struja teče kroz žicu i vrlo je jaka' }, { en: 'The wire is too thick, so the current cannot get through it', hr: 'Žica je predebela, pa struja ne može proći kroz nju' }, { en: 'The wire used up the current before it reached the bulb', hr: 'Žica je potrošila struju prije nego što je došla do žarulje' }, { en: 'Copper is an insulator, so the circuit is now broken', hr: 'Bakar je izolator, pa je strujni krug sada prekinut' } ],
      answer: 0,
      explain: { en: 'Current takes the easier path: the thick wire has far less resistance than the thin filament of the bulb, so almost nothing flows through the bulb. With so little resistance in the circuit the current becomes very large, heats the wire and quickly drains or damages the battery. Fuses protect against this, and you should never short-circuit a battery.',
                 hr: 'Struja ide lakšim putem: debela žica ima daleko manji otpor od tanke niti žarulje, pa kroz žarulju ne teče gotovo ništa. Uz tako mali otpor u krugu struja postane vrlo jaka, grije žicu i brzo isprazni ili ošteti bateriju. Od toga štite osigurači, a bateriju nikad ne smiješ kratko spojiti.' },
      misconception: { en: '"One more wire brings more current to the bulb." A wire joined across a bulb does not feed it; it leads the current past it.',
                       hr: '"Još jedna žica dovodi više struje žarulji." Žica spojena preko žarulje ne opskrbljuje je, nego struju vodi mimo nje.' } },

    { id: 't2-balloon-hair-charge', topic: 'electricity', type: 'mc', format: 'contentions', level: 1,
      q: { en: 'Petra rubs a balloon on her dry hair. Afterwards her hair rises towards the balloon. Ana says: "Rubbing created new electric charge in the balloon." Marko says: "Rubbing moved electrons from the hair to the balloon, so the balloon is now negative and the hair positive." Iva says: "Rubbing turned the balloon into a magnet." Who is right?',
           hr: 'Petra trlja balon o suhu kosu. Nakon toga kosa joj se diže prema balonu. Ana kaže: "Trljanjem je u balonu nastao novi električni naboj." Marko kaže: "Trljanjem su elektroni prešli s kose na balon, pa je balon sada negativan, a kosa pozitivna." Iva kaže: "Trljanjem je balon postao magnet." Tko ima pravo?' },
      options: [ { en: 'Ana', hr: 'Ana' }, { en: 'Marko', hr: 'Marko' }, { en: 'Iva', hr: 'Iva' }, { en: 'none of them', hr: 'nitko od njih' } ],
      answer: 1,
      explain: { en: 'Every body contains enormous, equal amounts of positive and negative charge. Rubbing only moves some electrons from one body to the other: the balloon gains them and becomes negative, the hair loses them and becomes positive, and opposite charges attract. The total charge stays the same; nothing is created.',
                 hr: 'Svako tijelo sadrži goleme i jednake količine pozitivnog i negativnog naboja. Trljanjem samo dio elektrona prijeđe s jednog tijela na drugo: balon ih primi i postane negativan, kosa ih izgubi i postane pozitivna, a raznoimeni naboji se privlače. Ukupni naboj ostaje isti; ništa ne nastaje.' },
      misconception: { en: '"Friction makes electricity." Charge is never made, only separated. And electric attraction is not magnetism: a charged balloon attracts hair and bits of paper, which a magnet does not.',
                       hr: '"Trenjem nastaje elektricitet." Naboj nikad ne nastaje, samo se razdvaja. A električno privlačenje nije magnetizam: nabijeni balon privlači kosu i papiriće, što magnet ne čini.' } },

    { id: 't2-rank-current-ohm', topic: 'electricity', type: 'rank', level: 2,
      q: { en: 'Rank from the largest current through the resistor to the smallest.', hr: 'Poredaj od najjače struje kroz otpornik do najslabije.' },
      items: [ { en: 'a 4 Ω resistor connected to 24 V', hr: 'otpornik od 4 Ω spojen na 24 V' }, { en: 'a 3 Ω resistor connected to 12 V', hr: 'otpornik od 3 Ω spojen na 12 V' }, { en: 'a 4.5 Ω resistor connected to 9 V', hr: 'otpornik od 4,5 Ω spojen na 9 V' }, { en: 'a 12 Ω resistor connected to 6 V', hr: 'otpornik od 12 Ω spojen na 6 V' } ],
      explain: { en: 'I = U / R: 24 V / 4 Ω = 6 A, 12 V / 3 Ω = 4 A, 9 V / 4.5 Ω = 2 A and 6 V / 12 Ω = 0.5 A. A larger voltage drives more current and a larger resistance lets less through, so you must look at both.',
                 hr: 'I = U / R: 24 V / 4 Ω = 6 A, 12 V / 3 Ω = 4 A, 9 V / 4,5 Ω = 2 A i 6 V / 12 Ω = 0,5 A. Veći napon tjera jaču struju, a veći otpor propušta slabiju, pa moraš gledati oboje.' } },

    { id: 't2-estimate-router-year-cost', topic: 'electricity', type: 'num', level: 3,
      q: { en: 'A Wi-Fi router with a power of 10 W is switched on day and night for a whole year. Estimate what its electricity costs per year, in euros, if 1 kWh costs 0.15 €.',
           hr: 'Wi-Fi usmjernik (ruter) snage 10 W uključen je dan i noć cijelu godinu. Procijeni koliko godišnje košta električna energija koju potroši, u eurima, ako 1 kWh košta 0,15 €.' },
      answer: 13, min: 11, max: 15, unit: '€',
      explain: { en: 'A year has 365 · 24 = 8760 hours. Energy: 0.01 kW · 8760 h ≈ 88 kWh. Cost: 88 kWh · 0.15 €/kWh ≈ 13 €. Small devices that never sleep add up: a tiny power for a very long time is a lot of energy.',
                 hr: 'Godina ima 365 · 24 = 8760 sati. Energija: 0,01 kW · 8760 h ≈ 88 kWh. Cijena: 88 kWh · 0,15 €/kWh ≈ 13 €. Mali uređaji koji nikad ne spavaju skupe se: mala snaga kroz vrlo dugo vrijeme znači mnogo energije.' } },

    /* ---------- MAGNETISM / MAGNETIZAM ---------- */
    { id: 't2-magnet-at-rest-in-coil', topic: 'magnetism', type: 'mc', format: 'whatif', level: 2,
      q: { en: 'While you push a bar magnet into a coil connected to a sensitive ammeter, the needle swings. Now the same strong magnet lies still inside the coil. What does the ammeter show?',
           hr: 'Dok štapićasti magnet guraš u zavojnicu spojenu na osjetljivi ampermetar, kazaljka se otklanja. Sada isti jaki magnet miruje u zavojnici. Što pokazuje ampermetar?' },
      options: [ { en: 'A steady current, because the magnet is inside the coil', hr: 'Stalnu struju, jer je magnet u zavojnici' }, { en: 'Zero: a current appears only while the magnet or the coil is moving', hr: 'Nulu: struja se javlja samo dok se magnet ili zavojnica gibaju' }, { en: 'A larger current than before, because the whole magnet is now inside', hr: 'Jaču struju nego prije, jer je sada cijeli magnet unutra' }, { en: 'A steady current in the opposite direction', hr: 'Stalnu struju suprotnog smjera' } ],
      answer: 1,
      explain: { en: 'A current is induced in a coil only while the magnetic field through it is changing: when the magnet moves in or out, or when the coil moves. A magnet at rest gives no current, however strong it is. Generators in power stations use this: magnets and coils must keep turning relative to each other.',
                 hr: 'Struja se u zavojnici inducira samo dok se magnetsko polje kroz nju mijenja: kad magnet ulazi ili izlazi ili kad se giba zavojnica. Magnet koji miruje ne daje struju, ma koliko bio jak. To koriste generatori u elektranama: magneti i zavojnice moraju se stalno vrtjeti jedni u odnosu na druge.' },
      misconception: { en: '"A magnet near a wire produces a current." If that were true, we would get energy for nothing. What counts is change, and the energy comes from the work done in moving the magnet.',
                       hr: '"Magnet u blizini žice stvara struju." Da je to točno, dobivali bismo energiju ni iz čega. Važna je promjena, a energija dolazi od rada uloženog u gibanje magneta.' } },

    { id: 't2-big-small-magnet-forces', topic: 'magnetism', type: 'mc', format: 'compare', level: 2,
      q: { en: 'A large, strong magnet and a small, weak magnet lie on a table with opposite poles facing each other, and they attract. Compare the force of the large magnet on the small one with the force of the small magnet on the large one.',
           hr: 'Veliki, jaki magnet i mali, slabi magnet leže na stolu okrenuti jedan prema drugome raznoimenim polovima i privlače se. Usporedi silu kojom veliki magnet djeluje na mali sa silom kojom mali magnet djeluje na veliki.' },
      options: [ { en: 'The large magnet pulls harder', hr: 'Veliki magnet privlači jače' }, { en: 'The small magnet pulls harder', hr: 'Mali magnet privlači jače' }, { en: 'The two forces are equally big', hr: 'Te su dvije sile jednako velike' }, { en: 'Only the large magnet pulls; the small one is just pulled', hr: 'Privlači samo veliki magnet; mali je samo privučen' } ],
      answer: 2,
      explain: { en: 'Attraction is one interaction between two bodies, and both feel it equally: the forces are equal in size and opposite in direction (Newton\'s third law). The small magnet starts to move first only because it has less mass and less friction to overcome. The same holds for a magnet and an iron nail: the nail pulls the magnet exactly as hard as the magnet pulls the nail.',
                 hr: 'Privlačenje je jedno međudjelovanje dvaju tijela i oba ga osjećaju jednako: sile su jednakog iznosa i suprotnog smjera (treći Newtonov zakon). Mali magnet prvi se pokrene samo zato što ima manju masu i mora svladati manje trenje. Isto vrijedi za magnet i željezni čavao: čavao privlači magnet točno jednako jako kao magnet čavao.' },
      misconception: { en: '"The stronger magnet exerts the bigger force." How strong the magnets are decides how big both forces are, but the two forces are always equal to each other.',
                       hr: '"Jači magnet djeluje većom silom." Jakost magneta određuje koliko su obje sile velike, ali te su dvije sile uvijek međusobno jednake.' } },

    /* ---------- WAVES / VALOVI ---------- */
    { id: 't2-pluck-harder-pitch', topic: 'waves', type: 'mc', format: 'whatif', level: 1,
      q: { en: 'You pluck a guitar string gently. Then you pluck the same string much harder, changing nothing else. What changes in the sound?',
           hr: 'Lagano trzneš žicu gitare. Zatim istu žicu trzneš mnogo jače, a ništa drugo ne promijeniš. Što se mijenja u zvuku?' },
      options: [ { en: 'It is louder, but the pitch is the same', hr: 'Glasniji je, ali je visina tona ista' }, { en: 'It is higher, but just as loud', hr: 'Viši je, ali jednako glasan' }, { en: 'It is both louder and higher', hr: 'I glasniji je i viši' }, { en: 'It is louder and travels faster through the air', hr: 'Glasniji je i brže putuje zrakom' } ],
      answer: 0,
      explain: { en: 'Plucking harder makes the string swing with a larger amplitude, and a larger amplitude means a louder sound. The pitch depends on the frequency, which is set by the length, tension and thickness of the string, and none of these has changed. For a higher tone you must shorten the string with a finger or tighten it.',
                 hr: 'Jačim trzanjem žica titra s većom amplitudom, a veća amplituda znači glasniji zvuk. Visina tona ovisi o frekvenciji, koju određuju duljina, napetost i debljina žice, a ništa se od toga nije promijenilo. Za viši ton žicu moraš prstom skratiti ili je jače napeti.' },
      misconception: { en: 'Pupils often mix up "higher" and "louder". Loudness goes with amplitude and pitch with frequency, and the speed of sound depends on neither.',
                       hr: 'Učenici često miješaju "viši" i "glasniji" ton. Glasnoća je povezana s amplitudom, a visina tona s frekvencijom; brzina zvuka ne ovisi ni o jednoj.' } },

    { id: 't2-ball-on-waves', topic: 'waves', type: 'mc', format: 'contentions', level: 1,
      q: { en: 'A ball floats on the sea off the beach at Makarska, far enough out that the waves do not break. Waves pass under it, one after another, on their way to the shore; there is no wind and no current. Ana says: "The waves will carry the ball to the beach." Marko says: "The ball only bobs up and down in the same place; a wave carries energy, not water." Iva says: "The ball will drift out to sea, against the waves." Who is right?',
           hr: 'Lopta pluta na moru pred plažom u Makarskoj, dovoljno daleko da se valovi ondje još ne lome. Ispod nje prolaze valovi, jedan za drugim, prema obali; nema ni vjetra ni morske struje. Ana kaže: "Valovi će loptu odnijeti do plaže." Marko kaže: "Lopta se samo ljulja gore-dolje na istome mjestu; val prenosi energiju, a ne vodu." Iva kaže: "Lopta će otploviti prema pučini, suprotno od valova." Tko ima pravo?' },
      options: [ { en: 'Ana', hr: 'Ana' }, { en: 'Marko', hr: 'Marko' }, { en: 'Iva', hr: 'Iva' }, { en: 'none of them', hr: 'nitko od njih' } ],
      answer: 1,
      explain: { en: 'A wave is a disturbance that travels, while the water itself only moves up and down, in small circles around the same place. So the ball bobs but does not travel with the wave. What the wave brings to the shore is energy; you feel it when a wave pushes against you.',
                 hr: 'Val je poremećaj koji putuje, dok se sama voda samo giba gore-dolje, u malim krugovima oko istoga mjesta. Zato se lopta ljulja, ali ne putuje s valom. Val do obale donosi energiju; osjetiš je kad te val gurne.' },
      misconception: { en: 'Pupils often picture a wave as a mass of water (or of air, for sound) that travels along. With sound, too, the air does not travel from the loudspeaker to your ear; only the vibration does.',
                       hr: 'Učenici val često zamišljaju kao masu vode (ili zraka, kod zvuka) koja putuje. Ni kod zvuka zrak ne putuje od zvučnika do tvojeg uha; putuje samo titranje.' } },

    { id: 't2-rank-wavelength-sound', topic: 'waves', type: 'rank', level: 2,
      q: { en: 'Four sounds travel through the same air (speed of sound 340 m/s). Rank them from the longest wavelength to the shortest.',
           hr: 'Četiri zvuka šire se istim zrakom (brzina zvuka 340 m/s). Poredaj ih od najveće valne duljine do najmanje.' },
      items: [ { en: 'the 100 Hz hum of a transformer', hr: 'zujanje transformatora frekvencije 100 Hz' }, { en: 'the 440 Hz tone of a tuning fork', hr: 'ton glazbene vilice frekvencije 440 Hz' }, { en: 'a 1000 Hz whistle', hr: 'zvižduk frekvencije 1000 Hz' }, { en: 'a 5000 Hz chirp of a bird', hr: 'cvrkut ptice frekvencije 5000 Hz' } ],
      explain: { en: 'All four travel at the same speed, and v = λ · f, so λ = v / f: the lower the frequency, the longer the wave. 100 Hz gives 3.4 m, 440 Hz about 77 cm, 1000 Hz 34 cm and 5000 Hz about 7 cm. Deep tones have waves as long as a room, high tones as short as a finger.',
                 hr: 'Sva se četiri šire jednakom brzinom, a v = λ · f, pa je λ = v / f: što je frekvencija niža, val je dulji. Za 100 Hz dobijemo 3,4 m, za 440 Hz oko 77 cm, za 1000 Hz 34 cm, a za 5000 Hz oko 7 cm. Duboki tonovi imaju valove duge kao soba, a visoki kratke kao prst.' } },

    /* ---------- LIGHT / SVJETLOST ---------- */
    { id: 't2-mirror-step-closer', topic: 'light', type: 'num', level: 2,
      q: { en: 'You stand 2 m in front of a large plane mirror. Then you take a step of 0.5 m towards the mirror. How far are you now from your own image, in metres?',
           hr: 'Stojiš 2 m ispred velikog ravnog zrcala. Zatim napraviš korak od 0,5 m prema zrcalu. Kolika je sada udaljenost između tebe i tvoje slike, u metrima?' },
      answer: 3, min: 2.9, max: 3.1, unit: 'm',
      explain: { en: 'The image in a plane mirror is not on the glass: it lies behind the mirror, exactly as far behind it as you are in front of it. After the step you are 1.5 m from the mirror and your image is 1.5 m behind it, so you are 3 m apart. Each step of 0.5 m towards the mirror brings you 1 m closer to your image.',
                 hr: 'Slika u ravnom zrcalu nije na staklu: nalazi se iza zrcala, točno onoliko iza njega koliko si ti ispred njega. Nakon koraka ti si 1,5 m od zrcala, a slika je 1,5 m iza njega, pa je udaljenost između vas 3 m. Svakim korakom od 0,5 m prema zrcalu približiš se svojoj slici za 1 m.' } },

    { id: 't2-blue-shirt-red-light', topic: 'light', type: 'mc', format: 'whatif', level: 2,
      q: { en: 'In white light Ana\'s T-shirt is pure blue. On stage the white lamps are switched off and only pure red spotlights shine. What does the T-shirt look like now?',
           hr: 'Na bijeloj svjetlosti Anina je majica čisto plava. Na pozornici se ugase bijela svjetla i svijetle samo čisto crveni reflektori. Kako majica sada izgleda?' },
      options: [ { en: 'Almost black', hr: 'Gotovo crno' }, { en: 'Blue; an object keeps its colour', hr: 'Plavo; predmet zadržava svoju boju' }, { en: 'Red', hr: 'Crveno' }, { en: 'Purple; red and blue mix', hr: 'Ljubičasto; crvena i plava se miješaju' } ],
      answer: 0,
      explain: { en: 'A blue T-shirt looks blue because it reflects blue light and absorbs the other colours. The red spotlights send no blue light, and the red light is absorbed, so almost nothing is reflected into your eyes and the T-shirt looks nearly black. The colour we see depends on the object and on the light that falls on it.',
                 hr: 'Plava majica izgleda plavo jer odbija plavu svjetlost, a ostale boje upija. Crveni reflektori ne šalju plavu svjetlost, a crvenu majica upije, pa se u tvoje oči ne odbija gotovo ništa i majica izgleda gotovo crno. Boja koju vidimo ovisi o predmetu i o svjetlosti koja na njega pada.' },
      misconception: { en: '"Colour is a fixed property of the object", or "coloured light mixes with the object\'s colour like paints". An object can only reflect colours that are present in the light shining on it.',
                       hr: '"Boja je stalno svojstvo predmeta" ili "obojena svjetlost miješa se s bojom predmeta kao tempere". Predmet može odbiti samo one boje koje postoje u svjetlosti koja ga obasjava.' } },

    { id: 't2-half-covered-lens', topic: 'light', type: 'mc', format: 'whatif', level: 3,
      q: { en: 'A magnifying glass (a converging lens) throws a sharp, upside-down image of a bright window onto a sheet of paper. You cover the upper half of the lens with a piece of cardboard. What happens to the image?',
           hr: 'Povećalo (sabirna leća) na listu papira stvara oštru, obrnutu sliku svijetlog prozora. Gornju polovicu leće pokriješ komadom kartona. Što se događa sa slikom?' },
      options: [ { en: 'Half of the image disappears', hr: 'Nestane polovica slike' }, { en: 'The whole image is still there, only dimmer', hr: 'Cijela je slika i dalje tu, samo je tamnija' }, { en: 'The whole image disappears', hr: 'Nestane cijela slika' }, { en: 'The image becomes half as big', hr: 'Slika postane dvostruko manja' } ],
      answer: 1,
      explain: { en: 'From every point of the window light reaches every part of the lens, and every part of the lens sends it to the same point of the image. Half a lens therefore still forms the whole image, only with half the light, so it is dimmer. For the same reason a partly covered camera lens still gives a complete photograph.',
                 hr: 'Iz svake točke prozora svjetlost dolazi na svaki dio leće, a svaki dio leće šalje je u istu točku slike. Zato i pola leće stvara cijelu sliku, samo s upola manje svjetlosti, pa je slika tamnija. Iz istog razloga djelomično pokriven objektiv fotoaparata i dalje daje cijelu fotografiju.' },
      misconception: { en: 'Many imagine that the picture travels through the lens ready-made, its top through one half of the lens and its bottom through the other. In fact every part of the lens helps to form every point of the image.',
                       hr: 'Mnogi zamišljaju da slika prolazi kroz leću već gotova, gornji dio kroz jednu polovicu leće, a donji kroz drugu. Zapravo svaki dio leće sudjeluje u stvaranju svake točke slike.' } },

    { id: 't2-shadow-tree-height', topic: 'light', type: 'num', level: 2,
      q: { en: 'On a sunny day a 1 m stick standing upright casts a shadow 1.5 m long. At the same moment a tree casts a shadow 12 m long. How tall is the tree, in metres?',
           hr: 'Za sunčanog dana uspravan štap visok 1 m baca sjenu dugu 1,5 m. U istom trenutku stablo baca sjenu dugu 12 m. Koliko je stablo visoko, u metrima?' },
      answer: 8, min: 7.5, max: 8.5, unit: 'm',
      explain: { en: 'The Sun\'s rays are parallel, so at the same moment the heights of objects and the lengths of their shadows are proportional. The tree\'s shadow is 12 m / 1.5 m = 8 times longer than the stick\'s shadow, so the tree is 8 times taller than the stick: 8 m. Thales is said to have measured the height of a pyramid in this way.',
                 hr: 'Sunčeve zrake su usporedne, pa su u istom trenutku visine tijela i duljine njihovih sjena proporcionalne. Sjena stabla je 12 m / 1,5 m = 8 puta dulja od sjene štapa, pa je stablo 8 puta više od štapa: 8 m. Priča se da je Tales tako izmjerio visinu piramide.' } },

    /* ---------- SPACE / SVEMIR ---------- */
    { id: 't2-seasons-tilt', topic: 'space', type: 'mc', format: 'contentions', level: 2,
      q: { en: 'Why is it warmer in Croatia in July than in January? Ana says: "In summer Earth is closer to the Sun." Marko says: "Earth\'s axis is tilted. In our summer the northern half of Earth leans towards the Sun, so the Sun is higher in the sky and the days are longer." Iva says: "In summer the Sun itself shines more strongly." Who is right?',
           hr: 'Zašto je u Hrvatskoj u srpnju toplije nego u siječnju? Ana kaže: "Ljeti je Zemlja bliže Suncu." Marko kaže: "Zemljina os je nagnuta. Za našeg ljeta sjeverna je polovica Zemlje nagnuta prema Suncu, pa je Sunce više na nebu, a dani su dulji." Iva kaže: "Ljeti samo Sunce jače sja." Tko ima pravo?' },
      options: [ { en: 'Ana', hr: 'Ana' }, { en: 'Marko', hr: 'Marko' }, { en: 'Iva', hr: 'Iva' }, { en: 'none of them', hr: 'nitko od njih' } ],
      answer: 1,
      explain: { en: 'Earth\'s axis is tilted by about 23.5°. In our summer the northern half leans towards the Sun: sunlight strikes the ground more steeply and the day lasts longer, so the ground receives much more energy. Distance is not the reason: Earth is actually closest to the Sun at the beginning of January, and when it is summer here, it is winter in Australia.',
                 hr: 'Zemljina os nagnuta je za oko 23,5°. Za našeg ljeta sjeverna je polovica nagnuta prema Suncu: Sunčeve zrake padaju na tlo strmije, a dan traje dulje, pa tlo prima mnogo više energije. Udaljenost nije razlog: Zemlja je Suncu zapravo najbliže početkom siječnja, a kad je kod nas ljeto, u Australiji je zima.' },
      misconception: { en: '"Summer means closer to the Sun" sounds sensible, because we are warmer close to a fire. But then the whole Earth would have summer at the same time.',
                       hr: '"Ljeto znači bliže Suncu" zvuči razumno, jer nam je uz vatru toplije. No tada bi cijela Zemlja imala ljeto u isto vrijeme.' } },

    { id: 't2-rank-distances-from-earth', topic: 'space', type: 'rank', level: 1,
      q: { en: 'Rank from the nearest to us to the farthest.', hr: 'Poredaj od najbližeg do najudaljenijeg od nas.' },
      items: [ { en: 'the International Space Station', hr: 'Međunarodna svemirska postaja' }, { en: 'the Moon', hr: 'Mjesec' }, { en: 'the Sun', hr: 'Sunce' }, { en: 'the planet Neptune', hr: 'planet Neptun' }, { en: 'the star Proxima Centauri', hr: 'zvijezda Proxima Centauri' } ],
      explain: { en: 'The space station circles only about 400 km above us, the Moon is about 384 000 km away, the Sun 150 million km, Neptune about 4.5 billion km, and Proxima Centauri, the nearest star after the Sun, about 40 000 billion km. Light needs 1.3 s from the Moon, 8 minutes from the Sun, about 4 hours from Neptune and 4.2 years from Proxima Centauri.',
                 hr: 'Svemirska postaja kruži samo oko 400 km iznad nas, Mjesec je udaljen oko 384 000 km, Sunce 150 milijuna km, Neptun oko 4,5 milijardi km, a Proxima Centauri, najbliža zvijezda nakon Sunca, oko 40 000 milijardi km. Svjetlosti treba 1,3 s od Mjeseca, 8 minuta od Sunca, oko 4 sata od Neptuna i 4,2 godine od Proxime Centauri.' } },

    /* ---------- SCIENCE / KAKO ZNANOST RADI ---------- */
    { id: 't2-two-variables-at-once', topic: 'science', type: 'mc', format: 'troubleshoot', level: 2,
      q: { en: 'Iva wants to find out whether the period of a pendulum depends on the length of the string. She times a pendulum with a 20 cm string and a 50 g weight, and then a pendulum with a 60 cm string and a 200 g weight. The second one swings more slowly, and she concludes: "A longer string gives a longer period." Where is the mistake in her experiment?',
           hr: 'Iva želi doznati ovisi li period njihala o duljini niti. Izmjeri period njihala s niti od 20 cm i utegom od 50 g, a zatim njihala s niti od 60 cm i utegom od 200 g. Drugo njihalo titra sporije i ona zaključi: "Dulja nit daje dulji period." Gdje je pogreška u njezinu pokusu?' },
      options: [ { en: 'She changed two things at once, the length and the mass, so she cannot tell which one caused the difference', hr: 'Promijenila je dvije stvari odjednom, duljinu i masu, pa ne može znati koja je uzrokovala razliku' }, { en: 'The second weight should have been even heavier', hr: 'Drugi je uteg trebao biti još teži' }, { en: 'She should also have changed the angle of release', hr: 'Trebala je promijeniti i kut otklona' }, { en: 'There is no mistake; the conclusion is correct', hr: 'Nema pogreške; zaključak je točan' } ],
      answer: 0,
      explain: { en: 'In a fair test you change only one variable (here the length) and keep all the others the same: the mass, the angle of release, the way of timing. Only then can a change in the result be put down to that one variable. Iva\'s conclusion happens to be true, but her experiment does not show it, because the heavier weight might have been the cause.',
                 hr: 'U poštenom pokusu mijenjaš samo jednu varijablu (ovdje duljinu), a sve ostale držiš jednakima: masu, kut otklona, način mjerenja vremena. Samo se tada promjena rezultata može pripisati toj jednoj varijabli. Ivin je zaključak slučajno točan, ali ga njezin pokus ne dokazuje, jer je uzrok mogao biti i teži uteg.' },
      misconception: { en: '"The conclusion is right, so the experiment is fine." A conclusion is worth only as much as the test behind it; with two variables changed at once it does not follow from the data.',
                       hr: '"Zaključak je točan, dakle pokus je dobar." Zaključak vrijedi samo onoliko koliko vrijedi pokus iza njega; kad se odjednom promijene dvije varijable, on ne slijedi iz podataka.' } },

    { id: 't2-which-is-hypothesis', topic: 'science', type: 'mc', level: 1,
      q: { en: 'A class is studying how ice melts. Which sentence is a hypothesis that an experiment can test?',
           hr: 'Razred istražuje kako se tali led. Koja je rečenica hipoteza koju se može provjeriti pokusom?' },
      options: [ { en: 'Why does ice melt?', hr: 'Zašto se led tali?' }, { en: 'If we sprinkle salt on an ice cube, it will melt faster than an ice cube without salt.', hr: 'Ako kockicu leda pospemo solju, rastalit će se brže nego kockica bez soli.' }, { en: 'Melting ice is the most interesting experiment.', hr: 'Taljenje leda najzanimljiviji je pokus.' }, { en: 'Our ice cube melted in 12 minutes.', hr: 'Naša se kockica leda rastalila za 12 minuta.' } ],
      answer: 1,
      explain: { en: 'A hypothesis is a clear claim that can be tested: it says what will happen and what it depends on, and an experiment can support it or show that it is wrong. A question is where research begins, an opinion cannot be tested, and a measurement is a result, not a prediction.',
                 hr: 'Hipoteza je jasna tvrdnja koju se može provjeriti: kaže što će se dogoditi i o čemu to ovisi, a pokus je može potkrijepiti ili pokazati da je pogrešna. Pitanje je početak istraživanja, mišljenje se ne može provjeriti, a mjerenje je rezultat, a ne predviđanje.' },
      misconception: { en: 'Many pupils call any question, guess or observation a "hypothesis". A hypothesis must make a prediction that could turn out to be false.',
                       hr: 'Mnogi učenici svako pitanje, nagađanje ili opažanje nazivaju "hipotezom". Hipoteza mora dati predviđanje koje bi se moglo pokazati netočnim.' } },

    { id: 't2-ten-swings-mean', topic: 'science', type: 'num', level: 3,
      q: { en: 'To find the period of a pendulum, Marko times 10 full swings three times and gets 18.0 s, 18.4 s and 17.9 s. What is his best value for the time of ONE swing, in seconds?',
           hr: 'Da odredi period njihala, Marko tri puta mjeri vrijeme 10 punih titraja i dobije 18,0 s, 18,4 s i 17,9 s. Koja je njegova najbolja vrijednost za vrijeme JEDNOG titraja, u sekundama?' },
      answer: 1.81, min: 1.78, max: 1.84, unit: 's',
      explain: { en: 'The mean of the three measurements is (18.0 + 18.4 + 17.9) s / 3 = 18.1 s for 10 swings, so one swing takes 1.81 s. Timing ten swings spreads the error of your reaction over ten periods, and the mean of repeated measurements evens out chance errors. The readings differ from the mean by at most 0.3 s, which is only 0.03 s per swing.',
                 hr: 'Srednja vrijednost triju mjerenja je (18,0 + 18,4 + 17,9) s / 3 = 18,1 s za 10 titraja, pa jedan titraj traje 1,81 s. Mjerenjem deset titraja pogreška tvoje reakcije raspodijeli se na deset perioda, a srednja vrijednost ponovljenih mjerenja ujednačuje slučajne pogreške. Očitanja se od srednje vrijednosti razlikuju najviše za 0,3 s, što je samo 0,03 s po titraju.' } }
  ]);
})();
